begin;
select plan(25);
insert into auth.users(id,instance_id,aud,role,email) values
('10000000-0000-4000-8000-000000000019','00000000-0000-0000-0000-000000000000','authenticated','authenticated','stock-boundary-a@test.local'),
('10000000-0000-4000-8000-000000000029','00000000-0000-0000-0000-000000000000','authenticated','authenticated','stock-boundary-b@test.local');
insert into stockkit.vendors(id,name) values('10000000-0000-4000-8000-000000000019','Boundary A'),('10000000-0000-4000-8000-000000000029','Boundary B');
insert into stockkit.products(id,vendor_id,name) values('20000000-0000-4000-8000-000000000029','10000000-0000-4000-8000-000000000029','Other vendor');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000019","role":"authenticated"}',true);
select lives_ok($$insert into stockkit.products(id,vendor_id,name,on_hand) values('20000000-0000-4000-8000-000000000019','10000000-0000-4000-8000-000000000019','Atomic stock',5)$$, 'owner creates product with automatic opening ledger');
select is((select count(*)::int from stockkit.stock_movements where product_id='20000000-0000-4000-8000-000000000019'), 1, 'opening trigger works without caller ledger INSERT');
select throws_ok($$update stockkit.products set on_hand=999 where id='20000000-0000-4000-8000-000000000019'$$, '42501', null, 'owner cannot rewrite quantity directly');
select throws_ok($$update stockkit.products set vendor_id='10000000-0000-4000-8000-000000000029' where id='20000000-0000-4000-8000-000000000019'$$, '42501', null, 'owner cannot transfer product ancestry');
select throws_ok($$insert into stockkit.stock_movements(vendor_id,product_id,delta,reason) values('10000000-0000-4000-8000-000000000019','20000000-0000-4000-8000-000000000019',9,'restock')$$, '42501', null, 'owner cannot append an unmatched ledger row');
select lives_ok($$update stockkit.products set name='Renamed',unit='bag',unit_cost_cents=100,low_stock_threshold=2,is_active=false where id='20000000-0000-4000-8000-000000000019'$$, 'metadata edit and archive remain allowed');
select lives_ok($$select stockkit.record_stock_movement('20000000-0000-4000-8000-000000000019',2,'restock','Delivery',100)$$, 'owner RPC records movement');
select is((select on_hand from stockkit.products where id='20000000-0000-4000-8000-000000000019'), 7::numeric, 'RPC updates running balance');
select is((select sum(delta) from stockkit.stock_movements where product_id='20000000-0000-4000-8000-000000000019'), 7::numeric, 'ledger and balance agree');
select throws_ok($$select stockkit.record_stock_movement('20000000-0000-4000-8000-000000000029',1,'restock')$$, '42501', null, 'definer RPC rejects another vendor product');
select throws_ok($$select stockkit.record_stock_movement('20000000-0000-4000-8000-000000000019',0,'restock')$$, '22023', null, 'RPC rejects invalid movement 10');
select throws_ok($$select stockkit.record_stock_movement('20000000-0000-4000-8000-000000000019','NaN'::numeric,'restock')$$, '22023', null, 'RPC rejects invalid movement 11');
select throws_ok($$select stockkit.record_stock_movement('20000000-0000-4000-8000-000000000019','Infinity'::numeric,'restock')$$, '22023', null, 'RPC rejects invalid movement 12');
select throws_ok($$select stockkit.record_stock_movement('20000000-0000-4000-8000-000000000019',1,'initial')$$, '22023', null, 'RPC rejects invalid movement 13');
select throws_ok($$select stockkit.record_stock_movement('20000000-0000-4000-8000-000000000019',1,'restock',repeat('x',501))$$, '22023', null, 'RPC rejects oversized note');
select throws_ok($$select stockkit.record_stock_movement('20000000-0000-4000-8000-000000000019',1,'restock',null,-1)$$, '22023', null, 'RPC rejects negative cost');
select throws_ok($$select stockkit.record_stock_movement('20000000-0000-4000-8000-000000000019',-8,'waste')$$, 'P0001', null, 'RPC rejects negative resulting stock');
select is((select on_hand from stockkit.products where id='20000000-0000-4000-8000-000000000019'), 7::numeric, 'rejected movement leaves balance intact');
select throws_ok($$select stockkit.record_stock_movement('20000000-0000-4000-8000-000000000019',-1,'restock')$$,'22023',null,'restock cannot decrease stock');
select throws_ok($$select stockkit.record_stock_movement('20000000-0000-4000-8000-000000000019',1,'waste')$$,'22023',null,'waste cannot increase stock');
reset role;
alter table stockkit.stock_movements add constraint ledger_boundary_failure check (reason <> 'adjustment') not valid;
set local role authenticated;
select throws_ok($$select stockkit.record_stock_movement('20000000-0000-4000-8000-000000000019',1,'adjustment')$$, '23514', null, 'ledger failure aborts RPC');
select is((select on_hand from stockkit.products where id='20000000-0000-4000-8000-000000000019'), 7::numeric, 'ledger failure rolls back quantity');
select is((select count(*)::int from stockkit.stock_movements where product_id='20000000-0000-4000-8000-000000000019'), 2, 'ledger failure leaves no extra row');
select set_config('request.jwt.claims','{"role":"authenticated"}',true);
select throws_ok($$select stockkit.record_stock_movement('20000000-0000-4000-8000-000000000019',1,'restock')$$, '42501', null, 'missing authenticated subject is rejected');
set local role anon;
select throws_ok($$select stockkit.record_stock_movement('20000000-0000-4000-8000-000000000019',1,'restock')$$, '42501', null, 'anonymous callers have no RPC privilege');
reset role;
select * from finish();
rollback;
